sketches.source:
setcpm(50/4)

// About five minutes: arrive, settle, go deeper, settle again, then let go
song("intro@4 settle@16 deepen@16 settle'@16 outro@8", "once")
// Steady, then easing back over the last eight bars
tempomap("0:12.5 52:12.5 60:10")

// A 10 Hz binaural beat in the alpha range: each ear is detuned by 5 Hz. Keep it quiet
// It is quieter still while arriving and letting go
drone: note("[d2,a2]").slow(4).s("sine").binaural(10)
  .attack(4).sustain(1).release(6).gain(bysec("intro:.08 outro:.08 *:.12"))

// A soft pad whose filter breathes over eight bars: Dmaj7, Bm7, Gmaj7, A
// On the second settle the room opens a little wider
pad: note("<[d3,a3,c#4,f#4] [b2,f#3,a3,d4] [g2,d3,b3,f#4] [a2,e3,a3,c#4]>").slow(2)
  .s("sawtooth").unison(3).detune(.2).lpf(sine.range(500, 1100).slow(8))
  .attack(3).release(4).room(.7).size(.9).gain(.12)
  .exceptSections("outro").variant(x => x.room(.85))

// The outro rests on Dmaj7, its filter closing as the section ends
home: note("[d3,a3,c#4,f#4]").slow(8).s("sawtooth").unison(3).detune(.2)
  .lpf(env("1000 400", "section")).attack(3).release(6).room(.8).size(.9).gain(.12)
  .sections("outro")

// A singing bowl marks every four bars
bowl: note("<d4 ~ ~ ~>").s("sine").fm(1.2).fmh(2.76)
  .decay(6).sustain(0).release(6).space("hall").gain(.14)

// High glass notes, only while going deeper
shimmer: n(irand(5).segment(2)).scale("D:major pentatonic").transpose(24)
  .degradeBy(.6).seed("settle").s("sine").decay(2).sustain(0).release(3)
  .room(.8).gain(.05).sections("deepen")

// Soft, wide air: unrelated pink noise in each ear, once you have arrived
air: s("pink").slow(8).icorr(.15).hpf(400).lpf(2500).gain(.025)
  .exceptSections("intro")

setcpm(56/4)

// About five minutes of reading; each primed pass reseeds the piano for new phrases
song("intro@8 read@16 read'@16 margin@8 read''@16 outro@8", "once")
// Steady, then slowing over the last eight bars
tempomap("0:14 64:14 72:11")

// A 6 Hz binaural beat in the theta range, following the roots: keep the volume low
drone: note("<d2 bb1 g1 a1>").slow(2).s("sine").binaural(6)
  .attack(3).sustain(1).release(4).gain(.14)

// Sparse piano from the minor pentatonic, never quite the same twice
// It plays while reading and in the outro, and rests in the margin
piano: n(irand(8).segment(4)).scale("D:minor pentatonic").transpose(12)
  .degradeBy(.55).seed("theta")
  .s("triangle").timbre("soft").attack(.005).decay(1.4).sustain(.08).release(1.6)
  .room(.6).size(.85).gain(.24).sections("read outro")

// Soft chords, two bars each: Dm, Bb, Gm, A
chords: note("<[d3,f3,a3] [bb2,d3,f3] [g2,bb2,d3] [a2,c#3,e3]>").slow(2)
  .s("triangle").timbre("soft").attack(2).sustain(.6).release(3)
  .lpf(900).room(.6).gain(.14)

// Rain beyond the window, heard through the glass
rain: s("rain").slow(4).intensity(.35).occlude(.6).gain(.16)

setcpm(48/4)

// Nearly five minutes: arrive in the centre, breathe, open out, breathe again, rest
song("arrive@8 breathe@16 open@8 breathe@16 rest@8", "once")
// The last breaths lengthen as the tempo eases
tempomap("0:12 48:12 56:9")

// The pad, named once: C, Am, F, G
const chords = note("<[c3,g3,e4] [a2,e3,c4] [f2,c3,a3] [g2,d3,b3]>").slow(2)
  .s("triangle").attack(2).sustain(1).release(3).lpf(1400)

// While breathing, the pad steps through the interaural phase, a chord at a time
// 0 degrees: centred. 90: looser. 180: diffuse and all around, and nearly gone in mono
pad: chords.iphase("<0 0 90 90 180 180 90 90>").gain(.18).sections("breathe")

// Arriving and resting, it sits in phase in the centre of your head
centre: chords.gain(.18).sections("arrive rest")

// Opening out, it stays at 180 degrees, all around you
haze: chords.iphase(180).gain(.18).sections("open")

// One breath every two bars, ten seconds: breathe in as the air rises, out as it fades
breath: s("pink").slow(2).hpf(200).lpf(700).attack(4).release(5).gain(.04)

// Far-off bells every few breaths, once you have arrived
bell: note("<g4 ~ e4 ~ c5 ~ ~ ~>").s("sine").fm(2).fmh(2.76)
  .decay(4).sustain(0).release(4).room(.7).gain(.08).sections("breathe open")

// A low root, the same in both ears
bass: note("<c2 a1 f1 g1>").slow(2).s("sine").attack(2).sustain(.8).release(3).gain(.2)

setcpm(64/4)

// Over four minutes at the desk: a draft, a second draft, a pause, a revision in Bb, a close
song("intro@4 draft@16 draft'@16 pause@8 revise@16 outro@8", "once")
// Steady, then slowing over the last eight bars
tempomap("0:16 60:16 68:12")

// A low-pass on each ear alone, sweeping in opposite directions every eight bars
// The level stays put; only the brightness drifts: Fmaj7, Dm7, Bbmaj7, C
// The revision moves to Bb (Bbmaj7, Gm7, Ebmaj7, F); the second draft plays backwards
figure: n("0 2 4 6 4 2 0 2").add("<0 -2 -4 -3>").scale(bysec("revise:Bb:major *:F:major"))
  .s("triangle").timbre("soft")
  .lcutoff(saw.range(500, 3000).slow(8)).rcutoff(isaw.range(500, 3000).slow(8))
  .attack(.005).decay(.8).sustain(.05).release(1).room(.5).gain(.2)
  .sections("draft revise outro").variant(x => x.rev())

// A low root, the same in both ears, a fourth higher in the revision
bass: note("<f2 d2 bb1 c2>").add(bysec("revise:5 *:0")).s("sine")
  .attack(.3).sustain(.6).release(1).gain(.26)

// A fire on your left, a clock on your right, and a warm floor of brown noise
fire: s("fire").slow(4).intensity(.25).density(5).azimuth(-60).distance(3).gain(.12)
clock: s("tick ~ tick ~").azimuth(70).distance(4).gain(.04)
floor: s("brown").slow(8).lpf(500).gain(.06)

setcpm(44/4)

// About five minutes: the drone orbits, stills, orbits again and settles
song("intro@8 orbit@16 still@8 orbit'@16 outro@8", "once")
// Steady, then slowing over the last eight bars
tempomap("0:11 48:11 56:8")

// A low fifth, named once
const hum = note("[e2,b2]").s("sine").attack(2).sustain(1).release(2).gain(.2)

// irate turns the drone's phase between the ears, in turns per second
// All rates stay below 3 Hz, so no pulse warning is needed
drone: hum.irate("<.2 .4 .8 .4>").sections("orbit")

// In the intro, the still middle and the outro it turns only once every five seconds
calm: hum.irate(.2).sections("intro still outro")

// A hushed choir on slow chords: Em, C, Am, B
choir: note("<[e3,g3,b3] [c3,e3,g3] [a2,c3,e3] [b2,d#3,f#3]>").slow(2)
  .s("choir").syl("<oo ah oo oh>").attack(3).release(4).space("hall").gain(.18)

// Glass notes circling your head once every sixteen bars, a little above
// The second orbit is primed, so its notes are drawn afresh
glass: n(irand(6).segment(4)).scale("E:minor pentatonic").transpose(24)
  .degradeBy(.6).seed("orbit")
  .s("triangle").timbre("glass").decay(1).sustain(0).release(2)
  .azimuth(saw.range(-180, 180).slow(16)).elevation(20).distance(3).posglide(.5)
  .room(.6).gain(.08).sections("orbit")

setcpm(66/4)

// About four minutes; each primed pass reseeds the melody, so the hands never repeat a phrase
song("intro@4 hands@16 hands'@16 rest@8 hands''@16 outro@8", "once")
// Steady, then slowing over the last eight bars
tempomap("0:16.5 60:16.5 68:12")

// One seeded melody, and a soft felt touch, named once
const melody = n(irand(8).segment(8)).scale("A:minor pentatonic")
const felt = (x) => x.s("triangle").timbre("soft")
  .attack(.005).decay(1).sustain(.05).release(1.2).room(.6)

// ild makes the right ear louder; earswap flips it, so the hands trade ears every four bars
// The right hand joins after the intro and leaves before the outro
right: melody.transpose(12).degradeBy(.6).felt()
  .ild(6).earswap("<0 0 0 0 1 1 1 1>").seed("hands").gain(.22)
  .exceptSections("intro rest outro")
// The left hand plays throughout, resting with the right in the middle
left: melody.transpose(-12).undegradeBy(.3).felt()
  .ild(6).earswap("<1 1 1 1 0 0 0 0>").seed("hands").gain(.2)
  .exceptSections("rest")

// A held fifth, the same in both ears, and a stream far off
drone: note("[a1,e2]").slow(8).s("sine").attack(3).sustain(1).release(4).gain(.14)
stream: s("stream").slow(4).distance(5).gain(.12)

setcpm(60/4)

// About four minutes: the strings alone, the kalimba, a long drift, the kalimba an octave up, a close
song("intro@8 tines@16 drift@16 tines'@16 outro@8", "once")
// Steady, then slowing over the last eight bars
tempomap("0:15 56:15 64:11")

// earsh raises the right ear and lowers the left by half the value each
// The strings breathe out and back: 2, 4, 8, then 4 cents, two bars each: G, Em, C, D
pad: note("<[g2,d3,b3] [e2,b2,g3] [c3,g3,e4] [d3,a3,f#4]>").slow(2)
  .s("sawtooth").unison(2).detune(.1).earsh("<2 2 4 4 8 8 4 4>")
  .lpf(1000).attack(2).sustain(1).release(3).room(.7).size(.9).gain(.12)

// A plucked tine over a small wooden box
const kalimba = (x) => x.s("sine").fm(.8).fmh(5.4)
  .attack(.001).decay(1).sustain(0).release(.9).body("box").bodymix(.35).room(.4)

// The kalimba, the same in both ears, an octave higher on its second pass
tines: note("<[g4 b4 d4 d5] [e4 g4 b3 b4] [c4 e4 g4 c5] [d4 f#4 a3 a4]>").slow(2)
  .kalimba().gain(.22).sections("tines").variant(x => x.add(12))

// A light breeze
breeze: s("wind").slow(8).intensity(.15).gain(.06)

setcpm(58/4)

// About four minutes: the harp alone, the flute, a harp interlude, the flute lower, a close
song("intro@8 flute@16 interlude@8 flute'@16 outro@8", "once")
// Steady, then slowing over the last eight bars
tempomap("0:14.5 48:14.5 56:11")

// From about 1 to 30 ms a delay between the ears keeps the harp on the leading side but widens it
// C, Am, F, G
harp: note("<[c3 g3 e4 g3 c4 g3 e4 g3] [a2 e3 c4 e3 a3 e3 c4 e3] [f2 c3 a3 c3 f3 c3 a3 c3] [g2 d3 b3 d3 g3 d3 b3 d3]>")
  .s("triangle").timbre("soft").attack(.002).decay(1.2).sustain(0).release(1.2)
  .itd("<1 6 12 20>").room(.5).gain(.22)

// The flute sings in the centre, with no delay at all; an octave lower on its second verse
flute: note("<[e5@3 d5 c5@4] [c5@2 e5@2 a4@4] [a4@3 c5 f5@4] [d5@6 ~@2]>")
  .s("sine").timbre("hollow").vib(4.5).vibdepth(.1)
  .attack(.2).sustain(.6).release(1).room(.6).gain(.2)
  .sections("flute").variant(x => x.add(-12))

// A soft root, and rain heard through the glass
bass: note("<c2 a1 f1 g1>").s("sine").attack(.2).sustain(.6).release(1).gain(.26)
rain: s("rain").slow(4).intensity(.3).occlude(.6).gain(.14)

setcpm(52/4)

// About five minutes: a guided pass with the hint, two passes without it, a rest and a close
song("intro@4 guide@16 listen@16 rest@8 listen@16 outro@4", "once")
// Steady, then slowing over the last four bars
tempomap("0:13 60:13 64:10")

// Soft breaths of noise: the same in both ears, but one ear is phase-shifted in a narrow band
// Neither ear alone hears a tone; together they carry a slow phrase
tune: s("white*4").dichotic("<[392 440 494 440] [330 392 440 392] [294 330 392 330] [392 392 392 392]>")
  .dichoticq(30).attack(.15).sustain(1).release(.3).gain(.1)
  .sections("guide listen")

// A quiet hint: the first phrase on a sine, once every four bars, only at the start
hint: note("<[g4 a4 b4 a4] ~ ~ ~>").s("sine")
  .decay(.4).sustain(.2).release(.4).gain(.06)
  .sections("intro guide")

// A soft pad holding the key: G, Em, D, G
pad: note("<[g2,d3,b3] [e2,b2,g3] [d2,a2,f#3] [g2,d3,b3]>")
  .s("triangle").timbre("soft").attack(1.5).sustain(.6).release(3)
  .lpf(900).room(.6).gain(.12)

// A singing bowl at the start of each phrase
bowl: note("<g3 ~ ~ ~>").s("sine").fm(1.2).fmh(2.76)
  .decay(6).sustain(0).release(6).space("hall").gain(.12)

setcpm(72/4)

// Four minutes of focus in three passes, with a quiet lift between them
song("intro@4 focus@16 lift@8 focus'@16 lift@8 focus''@16 outro@4", "once")
// Steady, then slowing over the last four bars
tempomap("0:18 68:18 72:14")

// A 14 Hz binaural beat in the beta range: each ear is detuned by 7 Hz. Keep it very quiet
drone: note("[a2,e3]").slow(4).s("sine").binaural(14)
  .attack(3).sustain(1).release(4).gain(.07)

// earsplit("harmonics") alternates the pad's partials between the ears: Am, F, C, G
pad: note("<[a2,e3,c4] [f2,c3,a3] [c3,g3,e4] [g2,d3,b3]>")
  .s("sawtooth").earsplit("harmonics").lpf(1400)
  .attack(1).sustain(.8).release(2).room(.5).gain(.1)

// A gentle marimba figure, the same in both ears, only while focusing
// Later passes play the figure backwards
marimba: n("0 2 4 2 5 4 2 4").add("<0 -2 2 -1>").scale("A:minor").transpose(12)
  .s("sine").fm(.6).fmh(4).decay(.35).sustain(0).room(.3).gain(.18)
  .sections("focus").variant(x => x.rev())

// A soft kick on the downbeat, doubled in the last bar of each pass as a pickup
kick: s("bd ~ ~ ~").lpf(200).gain(.3).sections("focus").atEnd(1, x => x.ply(2))

// A centred root once the intro is over
bass: note("<a1 f1 c2 g1>").s("sine").attack(.1).sustain(.6).release(.8).gain(.26)
  .exceptSections("intro")

setcpm(54/3)

// One cycle is a bar of 3/4
// About three minutes: the box plays, a hush, the box winds down, and the room goes quiet
song("intro@8 box@16 hush@8 box'@16 outro@8", "once")
// Steady, then slowing over the last eight bars
tempomap("0:18 48:18 56:12")

// A 2 Hz binaural drone: each ear is detuned by 1 Hz, below the 3-30 Hz warning range
drone: note("[d2,a2]").slow(8).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.22)

// A music box floating a little above your head: D, A, Bm, G, D, G, A, D
// On its second pass it winds down to half speed
musicbox: note("<[f#5 e5 d5] [e5@2 c#5] [d5 b4 f#4] [g4@3] [a4 d5 f#5] [g5@2 b4] [a4 c#5 e5] [d5@3]>")
  .s("sine").fm(2).fmh(4).attack(.002).decay(1).sustain(0).release(1.5)
  .elevation(30).distance(2).room(.6).size(.85).gain(.16)
  .sections("box").variant(x => x.slow(2))

// A soft root on each downbeat, until the room goes quiet
bass: note("<d2 a1 b1 g1 d2 g1 a1 d2>").s("triangle").timbre("soft")
  .attack(.01).decay(1).sustain(0).release(1).gain(.18)
  .exceptSections("outro")

// Warm brown noise and crickets far away
bed: s("brown").slow(8).lpf(400).gain(.07)
crickets: s("insect").slow(4).distance(8).gain(.05)
